mapper.update:
update basket_leaderboard_run
set state = #{state}, error_message = #{errorMessage}, finished_time = #{finishedTime}, source_revision = #{sourceRevision}
where id = #{id}

mapper.select:
select id, division_id, scope_key, policy_id, purpose, source_revision, state, error_message, started_time, finished_time, create_time
from basket_leaderboard_run
where division_id = #{divisionId}
and scope_key = #{scopeKey}
order by id desc
limit 50

mapper.update:
update basket_leaderboard_snapshot
set is_public = 0, public_scope_key = null
where division_id = #{divisionId} and public_scope_key = #{scopeKey}

update basket_leaderboard_snapshot
set is_public = 1, public_scope_key = #{publicScopeKey}, published_at = #{publishedAt}
where id = #{id}

mapper.select:
select * from basket_leaderboard_entry
where run_id = #{runId}
and subject_type = #{subjectType}
order by subject_type, eligible desc, rank_no, event_team_id, event_player_id

select * from basket_leaderboard_entry
where snapshot_id = #{snapshotId} and eligible = 1
and subject_type = #{subjectType}

mapper.update:
update basket_leaderboard_setting
set featured_division_id = #{divisionId}, update_by = #{updateBy}, update_time = #{updateTime}
where id = 1
